using Microsoft.EntityFrameworkCore;

// Cosmos DB context demonstrating EF Core 9 breaking-change fixes.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE: EF Core 9 changed the default discriminator property
        // from "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must configure it explicitly to avoid data loss / query failures.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }

    // BREAKING CHANGE: EF Core 9 removed synchronous Cosmos DB query support.
    // All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
    public async Task<List<Product>> GetExpensiveProductsAsync()
    {
        return await Products.Where(p => p.Price > 100).ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public decimal Price { get; set; }
}

